\u007e\u007e\u006b\u0044\u0052\u0040\u0078\u0049\u0043\u006a\u005b\u0050\u0066\u0034\u006d\u006b\u0044\u0052\u0040\u0029\u0049\u0037\u0068\u006b\u0021\u007e\u005d\u0023\u0050\u0053\u003f\u0039\u0028\u006d\u005d\u0072\u006b\u0058\u0051\u005b\u0057\u0053\u006f\u0051\u002f\u0035\u004f\u002e\u0064\u0076\u0044\u0049\u0060\u0049\u0028\u0043\u0063\u0050\u0053\u003f\u0039\u0028\u006d\u005d\u0072\u006b\u0058\u004a\u003f\u0026\u0049\u0079\u0021\u0077\u0028\u0079\u0033\u0059\u0046\u0049\u0037\u0058\u006b\u004d\u0057\u0028\u007b\u0041\u0075\u003d\u0035\u0064\u0066\u007c\u0076\u0021\u002f\u002a\u004a\u004d\u0045\u0050\u0053\u003f\u0039\u0028\u006d\u005d\u0072\u006b\u0058\u0041\u0076\u0026\u0049\u0068\u0021\u0021\u0047\u0053\u0069\u0047\u006e\u0062\u002f\u003a\u0033\u007b\u0046\u0022\u0072\u0040\u0067\u0072\u0035\u0037\u0049\u0046\u0050\u0038\u003e\u004f\u002e\u007c\u0076\u0070\u0070\u004f\u002e\u0028\u0067\u0058\u002a\u005b\u002e\u0062\u0033\u0070\u004a\u0034\u005d\u0047\u0025\u0048\u0047\u0040\u0049\u0043\u006d\u005e\u0063\u0026\u0049\u0038\u0075\u003f\u007d\u0069\u0025\u003a\u0079\u0068\u0068\u0065\u0044\u004f\u0074\u0042\u003d\u0054\u006c\u0069\u007d\u0072\u0024\u004d\u0079\u005f\u0067\u006b\u0058\u0036\u0035\u0051\u0060\u0038\u0054\u002f\u0046\u0034\u005b\u007b\u003c\u002c\u0053\u003d\u005b\u0051\u0024\u0079\u0072\u0028\u006f\u0025\u0034\u0032\u0058\u0053\u0042\u0043\u0068\u0030\u005a\u0032\u0067\u005b\u0038\u0047\u002a\u0054\u0033\u0028\u0037\u006b\u0021\u0054\u006f\u0060\u0021\u007a\u0060\u0025\u0048\u0047\u0023\u0053\u004b\u0040\u0067\u0047\u007a\u003d\u0051\u004e\u006e\u003f\u0054\u0070\u002f\u0068\u003c\u0040\u007a\u0055\u0070\u006d\u0076\u003d\u0054\u0025\u0073\u0064\u003a\u003d\u0055\u0036\u004d\u0041\u003f\u0038\u002a\u002b\u0040\u0033\u0076\u0072\u0034\u0029\u006d\u007d\u0057\u0076\u006a\u0071\u0037\u005a\u0047\u006c\u004a\u0026\u004e\u0047\u0044\u0058\u003c\u0062\u003e\u0057\u002e\u0022\u004a\u0078\u005a\u0054\u0032\u007c\u007a\u0063\u004b\u003e\u002b\u0053\u006b\u0061\u002c\u007b\u005f\u002f\u002e\u0064\u002e\u0051\u007b\u003b\u0048\u0038\u006f\u0053\u0055\u0029\u002c\u0052\u0075\u005e\u002f\u004d\u002e\u007a\u007d\u0075\u0060\u0038\u006f\u003a\u005e\u004c\u0050\u0034\u0066\u003b\u007e\u004b\u0035\u007c\u007d\u0071\u0076\u0071\u0024\u0042\u0070\u0058\u0029\u0044\u0046\u002f\u002e\u0064\u002e\u0051\u007b\u003b\u0048\u004c\u007b\u0063\u0078\u005a\u0067\u0041\u003b\u0029\u007e\u0028\u0069\u007b\u0021\u006b\u0029\u0076\u0041\u0073\u003f\u003d\u0041\u0076\u0041\u0032\u0040\u0079\u0044\u0054\u007a\u0069\u002f\u0072\u006c\u0060\u0045\u0046\u0036\u0079\u0031\u0074\u0049\u004c\u0050\u0031\u0077\u006c\u0042\u0071\u0062\u002b\u0038\u007d\u0054\u006b\u005a\u003f\u003e\u006b\u0045\u003f\u006d\u006b\u002f\u0067\u005a\u0041\u0039\u007e\u006f\u005e\u0036\u0072\u0040\u003e\u0048\u007a\u004c\u0051\u0047\u0071\u0076\u0054\u007c\u0057\u004f\u003d\u002e\u0071\u006b\u006a\u007b\u0062\u003d\u0021\u003d\u0054\u002f\u0056\u004b\u002a\u0056\u0063\u007a\u0066\u0051\u0065\u003c\u0066\u005d\u0071\u0063\u002f\u0048\u0078\u0073\u0040\u005f\u005d\u0021\u0021\u0078\u003f\u0032\u0040\u0073\u0065\u0063\u005d\u0031\u0070\u007e\u0023\u0076\u0040\u0034\u0031\u0044\u003b\u002b\u0069\u004a\u0034\u0044\u0055\u006b\u0044\u0029\u0024\u0064\u0042\u006d\u0073\u003a\u006d\u0059\u0048\u003e\u0032\u0054\u004a\u0066\u004b\u0078\u0036\u0057\u0053\u0079\u0048\u0050\u007a\u0056\u002c\u0055\u007d\u0026\u0023\u002c\u003c\u0061\u0035\u0070\u003a\u007b\u007e\u0034\u007d\u0049\u003b\u0032\u006c\u007a\u0061\u0049\u003c\u0045\u0064\u005b\u005e\u0033\u004c\u004b\u0040\u004f\u0066\u005a\u002e\u0021\u002e\u0067\u0026\u0078\u006c\u0057\u003a\u0039\u004c\u0026\u004a\u0056\u003f\u0023\u007b\u0049\u002a\u0064\u0033\u0021\u006f\u0025\u0033\u0042\u0028\u0053\u004c\u0069\u0054\u005b\u007a\u0044\u0029\u004a\u003b\u0073\u0073\u007a\u005e\u0078\u0059\u0052\u0044\u0056\u0063\u003d\u0079\u0074\u005a\u0063\u0069\u0040\u007a\u0055\u0070\u006d\u0076\u0070\u0025\u005f\u0030\u005b\u0067\u0038\u007d\u0036\u0033\u0045\u0022\u004f\u0069\u004e\u0061\u003b\u0058\u003e\u0061\u0047\u0038\u005e\u0072\u005f\u006d\u0053\u0059\u0034\u0070\u006d\u004d\u0058\u005a\u007d\u004a\u0053\u0053\u0052\u0039\u0044\u0022\u003b\u005f\u002e\u0031\u003b\u0060\u003c\u0031\u0072\u0021\u003e\u0075\u004f\u0073\u002e\u002f\u0054\u007a\u004f\u0069\u007c\u0060\u0032\u003f\u0029\u004a\u0065\u0051\u007a\u007d\u0030\u0022\u0029\u006c\u0057\u0057\u004c\u0067\u0061\u0042\u0066\u0025\u005f\u006b\u0041\u002f\u0022\u007b\u0038\u006c\u006b\u0049\u003b\u0049\u0034\u0026\u0072\u006e\u0043\u004b\u0047\u0041\u0071\u0059\u0056\u0067\u0076\u003d\u0048\u0030\u0046\u0078\u0025\u0062\u0073\u004a\u006f\u0049\u0033\u003c\u0057\u0070\u0078\u0038\u0022\u006c\u003e\u006a\u006d\u0070\u003d\u006a\u006b\u0078\u004d\u0032\u003d\u004f\u0030\u0031\u0045\u0056\u007a\u0063\u004e\u005f\u006d\u005d\u003e\u0079\u006a\u003f\u0059\u0070\u0062\u004a\u006f\u0054\u0047\u006d\u0060\u007c\u0068\u0034\u0026\u0048\u0046\u0045\u0055\u004b\u0026\u0039\u007b\u004f\u005f\u0054\u0068\u0067\u0021\u0065\u0059\u002a\u007d\u002a\u0062\u0054\u005e\u005f\u0054\u007a\u003d\u005d\u002f\u0066\u005b\u0062\u007c\u0075\u003d\u0054\u0078\u0028\u0048\u0029\u005b\u0041\u002f\u002e\u0076\u006b\u0061\u0059\u005e\u0034\u006c\u0054\u0053\u005f\u006f\u0054\u003b\u004c\u006b\u0069\u0045\u007c\u003c\u002e\u0078\u0063\u006b\u0045\u007c\u0041\u0068\u0021\u0077\u0034\u003a\u0043\u0034\u0039\u0056\u006f\u0040\u0023\u0062\u007b\u006e\u0021\u0073\u0067\u0049\u0044\u002a\u0033\u006a\u0070\u0071\u0071\u0057\u0068\u0077\u0059\u0061\u003b\u0048\u0022\u0028\u0079\u0046\u004a\u0057\u0073\u006a\u003d\u0068\u002a\u0026\u0077\u002e\u003f\u0023\u0021\u002b\u0079\u0037\u0043\u0050\u007e\u0040\u0046\u0073\u0064\u0028\u0064\u006b\u0071\u002c\u0060\u0028\u0039\u005d\u0049\u0061\u004b\u0034\u006a\u003d\u004e\u007e\u0034\u0071\u006e\u0077\u002e\u007d\u003e\u006a\u0028\u0039\u002a\u0024\u0061\u005d\u0034\u004a\u005d\u005f\u004a\u0076\u006f\u003b\u005f\u0053\u005f\u003f\u0052\u006a\u0056\u0062\u0047\u0079\u0063\u003b\u0048\u004a\u0052\u0041\u004f\u0069\u007c\u0022\u0070\u0023\u002e\u007a\u003a\u0026\u0048\u0061\u007a\u0049\u0070\u004b\u0053\u0062\u0064\u0025\u004d\u005b\u002c\u004c\u0063\u0079\u0049\u0070\u0069\u0046\u0054\u0021\u005e\u0039\u0040\u0024\u0063\u0033\u007c\u0026\u005d\u005b\u0052\u005f\u003b\u0075\u0041\u0058\u0043\u004e\u0045\u004a\u0022\u0065\u0079\u0054\u0071\u0038\u005d\u0055\u0032\u0054\u002e\u002e\u0061\u0028\u0039\u004d\u0049\u0048\u003f\u0021\u004f\u005f\u0065\u003b\u007e\u0031\u0034\u002c\u0046\u0058\u005b\u007c\u0077\u0028\u0029\u0071\u0061\u0045\u0033\u0044\u005d\u007c\u0047\u006e\u0057\u0065\u0071\u002b\u005b\u0077\u007e\u007b\u003f\u0045\u006f\u007d\u006d\u007d\u0074\u0059\u007e\u006d\u007e\u0070\u0069\u0029\u0040\u0075\u0063\u006e\u007c\u004d\u0028\u0050\u006a\u0032\u006a\u003f\u0055\u0070\u0057\u0061\u0038\u0076\u0051\u0048\u007a\u004c\u0029\u007a\u0047\u007b\u0073\u005b\u0031\u004e\u002a\u006c\u0063\u007b\u0056\u0029\u0039\u0051\u0033\u0025\u0046\u002f\u0074\u0065\u0029\u0055\u0077\u0055\u0078\u0034\u004d\u005d\u005f\u0050\u0029\u0047\u0047\u006f\u0051\u005b\u0037\u004c\u002a\u005b\u0064\u003a\u007e\u005f\u003e\u005e\u0059\u007a\u0074\u005a\u002c\u0044\u0041\u007d\u0030\u005d\u005a\u0075\u003a\u0042\u006c\u0060\u005b\u0073\u002c\u002e\u0079\u0036\u002a\u0076\u0039\u002c\u0041\u0034\u002b\u006b\u0042\u0069\u0056\u004c\u0079\u003d\u0054\u0061\u0047\u0031\u0029\u006e\u0056\u004a\u005e\u0074\u007c\u0048\u0032\u002b\u0077\u0064\u002b\u0058\u005a\u0051\u0022\u003a\u0046\u0060\u003c\u007a\u0078\u0043\u005a\u002b\u0053\u004a\u004c\u0062\u0072\u0076\u003f\u0053\u003a\u005f\u003f\u004e\u0076\u0051\u0047\u004c\u0048\u007a\u0075\u0070\u004d\u0066\u005f\u0040\u004b\u002c\u004f\u0052\u004c\u003e\u0030\u006a\u003b\u002b\u003a\u0053\u005d\u0054\u0039\u0040\u0069\u0050\u007e\u002f\u0076\u0039\u004a\u006f\u0054\u004c\u0055\u0079\u007c\u0069\u0062\u004d\u0066\u0033\u0054\u0025\u002c\u0033\u0057\u0065\u0051\u006b\u006a\u006b\u003f\u0067\u0023\u0043\u006d\u0057\u004c\u0069\u0039\u005d\u0046\u007e\u0063\u006c\u0047\u007d\u0021\u005d\u0030\u0021\u006f\u0029\u0040\u003d\u0030\u002f\u0063\u0028\u006e\u0052\u0062\u006f\u0041\u0043\u0069\u004c\u0051\u006f\u007e\u0056\u0039\u0069\u0024\u007e\u0051\u003a\u0073\u0055\u0066\u006f\u0057\u0056\u0070\u004c\u004c\u0025\u004f\u0078\u006e\u0065\u0064\u0069\u005d\u0039\u0058\u0074\u0078\u0058\u006b\u007d\u002b\u0073\u0028\u004f\u0056\u0024\u0061\u006a\u002f\u0074\u0037\u0023\u007c\u006d\u0023\u0057\u003f\u006d\u0023\u0023\u0024\u0069\u006e\u0076\u006b\u003a\u005d\u006a\u003b\u006e\u005a\u007e\u005a\u0053\u006e\u006a\u0024\u003f\u0030\u0024\u0057\u006a\u0050\u005b\u0031\u0046\u0031\u0023\u0076\u006a\u0056\u004e\u007c\u003f\u0061\u0065\u0044\u003e\u005f\u0022\u004b\u006a\u0061\u003e\u0039\u0033\u0074\u005f\u0047\u002b\u0021\u0052\u0046\u0065\u0044\u0028\u0030\u006a\u0041\u0060\u0028\u0049\u0064\u0054\u0055\u006d\u0066\u002f\u003b\u0057\u005f\u006c\u004d\u0048\u0074\u006d\u0076\u0076\u0068\u006c\u0042\u0064\u0048\u0039\u003c\u0046\u007e\u0041\u0074\u0038\u006c\u005e\u006f\u0057\u002f\u0032\u0053\u006c\u002a\u0042\u003a\u007e\u005e\u0052\u002c\u0079\u0042\u0079\u003f\u0022\u002f\u004a\u004b\u0065\u0058\u0021\u0073\u003a\u004d\u004c\u0061\u007e\u003c\u003e\u0040\u005a\u0041\u0050\u0039\u0053\u007e\u007d\u0040\u0066\u0024\u003b\u0025\u0052\u0035\u004a\u003e\u0057\u0049\u005e\u006c\u0078\u004c\u0036\u003b\u0076\u0024\u0063\u007b\u0044\u003a\u0075\u0023\u0032\u005d\u0058\u003c\u0069\u0045\u003b\u0052\u0063\u0043\u0042\u0025\u0075\u002b\u0055\u0066\u002a\u0048\u004d\u005b\u0068\u0070\u006b\u002f\u0025\u0033\u005f\u0041\u0072\u0041\u0060\u003d\u0048\u007d\u006d\u002c\u0054\u0061\u002a\u0078\u0053\u0069\u0065\u0079\u0051\u0036\u0047\u006d\u006e\u0031\u0037\u0078\u003e\u0068\u0070\u007a\u0079\u0076\u007d\u007a\u0071\u007e\u005d\u0025\u0045\u006e\u0035\u0062\u0066\u006a\u006a\u0077\u0079\u0037\u003c\u0072\u002a\u005f\u0047\u0044\u0064\u004f\u0073\u002e\u0078\u0037\u0024\u0040\u0048\u0028\u0061\u0076\u0060\u0043\u002a\u0052\u004b\u0071\u0031\u0052\u0055\u005a\u0048\u0039\u0030\u007d\u006a\u0036\u0073\u0022\u0053\u0031\u0068\u006c\u0079\u007e\u006e\u006d\u0029\u006f\u003f\u002c\u0026\u0064\u0042\u0043\u0065\u0068\u006b\u0026\u003d\u007c\u0069\u0061\u0076\u0076\u0029\u0060\u0038\u0077\u0049\u0045\u0035\u0046\u004d\u004b\u007d\u0055\u0070\u002e\u004e\u0044\u0054\u0041\u005b\u0030\u0068\u0068\u0040\u0077\u006b\u0075\u0077\u006e\u006c\u005d\u0074\u003f\u0074\u0045\u002e\u004c\u007a\u0071\u006e\u006e\u006f\u0054\u0072\u0051\u0075\u0040\u007a\u0059\u0070\u0040\u004a\u006f\u0054\u0062\u0029\u005f\u0030\u0038\u007d\u006b\u003c\u0064\u0042\u002c\u0040\u007a\u0059\u0070\u0040\u004a\u0057\u006e\u0026\u004f\u0023\u003e\u0078\u003e\u0079\u0054\u007d\u002a\u0062\u0057\u0039\u007d\u0042\u0076\u0067\u004e\u003c\u0069\u0045\u007c\u0075\u006e\u005b\u007b\u0063\u0037\u0046\u0038\u007d\u0067\u0047\u0074\u002f\u0057\u0076\u0037\u004a\u0074\u0054\u007c\u004f\u0049\u0062\u005b\u007e\u002f\u003b\u0049\u0034\u0026\u0061\u0069\u005d\u0054\u005d\u0068\u0047\u003b\u0049\u0034\u0026\u0064\u0067\u0064\u0054\u0030\u004f\u0068\u0078\u0077\u0060\u0069\u004a\u0071\u0039\u004a\u0043\u0034\u0073\u006f\u003f\u002c\u0026\u0062\u004a\u002b\u0077\u006a\u003d\u0065\u0032\u0039\u007a\u0049\u0066\u003e\u0063\u0052\u005b\u0052\u0024\u0029\u0038\u0076\u0048\u002e\u0056\u0045\u006f\u006d\u0078\u006e\u0038\u004a\u006b\u0066\u0056\u0060\u0075\u0052\u0024\u0054\u0033\u0065\u0037\u0037\u0048\u007e\u0045\u005e\u006b\u006e\u006c\u0024\u005b\u007d\u003f\u0071\u003f\u0037\u0045\u0030\u0042\u0044\u0069\u0031\u0024\u0046\u003f\u0051\u002f\u0075\u006c\u0025\u007c\u004f\u0045\u0051\u0056\u003c\u0028\u004d\u0044\u006f\u005f\u0032\u0067\u004f\u0043\u005e\u0062\u004c\u0065\u0038\u004b\u0073\u0070\u0078\u004f\u002f\u006c\u0072\u0026\u004a\u002a\u0051\u002a\u003e\u003c\u003b\u007e\u0066\u0025\u005e\u0066\u0035\u0026\u003b\u002f\u005e\u007b\u0024\u0047\u0074\u0043\u0046\u004a\u0076\u0030\u003e\u0039\u0043